"""rfrt — runtime for RobotFlow apps generated by rflowc (ADR-0067 §5).

The app talks only to Protobus (gRPC protobus.v1). It never imports ROS. Every node writes a trace line
`RFTRACE {json}` on stdout so the control API and the studio can show the running block, logs and results.
Safety: control lease taken lazily and renewed; velocity is refreshed at 20 Hz and always ends at zero;
a condition on STALE data never chooses a branch; on exit the lease is released (broker sends safe values).
"""
from __future__ import annotations

import asyncio
import json
import os
import re
import signal
import sys
import time
import uuid
from dataclasses import dataclass, field
from typing import Callable

import grpc

from protobus.v1 import protobus_pb2 as pb
from protobus.v1 import protobus_pb2_grpc as rpc
from protobus.wire import from_value, to_struct

VERSION = "0.1.0"
TEMPLATE = re.compile(r"\{\{\s*(Robot(?:\.[A-Za-z][A-Za-z0-9]*)+)\s*\}\}")


class Stale(Exception):
    """A signal needed by a condition is not fresh (STALE/UNAVAILABLE)."""


@dataclass(frozen=True)
class Behavior:
    trigger: str
    kind: str          # on_start | on_condition | every
    entry: str | None
    cond: Callable | None = None
    for_ms: int = 0
    repeat: bool = False
    period_ms: int = 0


@dataclass(frozen=True)
class Flow:
    signals: list
    nodes: dict
    behaviors: list = field(default_factory=list)


class Runtime:
    def __init__(self, flow: Flow, broker: str, safety: str, run_id: str, out=sys.stdout):
        self.flow, self.broker_target, self.safety_target = flow, broker, safety
        self.run_id = run_id
        self.out = out
        self.values: dict[str, tuple] = {}
        self.lease: pb.Lease | None = None
        self.lease_lock = asyncio.Lock()
        self.counters: dict[str, int] = {}
        self.busy: set[str] = set()
        self.tasks: list[asyncio.Task] = []
        self.stopping = False

    # ------------------------------------------------------------ trace

    def trace(self, event: str, **fields) -> None:
        line = json.dumps({"t": round(time.time(), 3), "run": self.run_id, "ev": event, **fields}, ensure_ascii=False)
        self.out.write("RFTRACE " + line + "\n")
        self.out.flush()

    # ------------------------------------------------------------ signals

    def v(self, path: str):
        value = self.values.get(path)
        if value is None or value[1] != pb.OK:
            raise Stale(path)
        return value[0]

    async def _subscribe(self) -> None:
        if not self.flow.signals:
            return
        while not self.stopping:
            try:
                stream = self.broker.Subscribe(pb.SubscribeRequest(paths=list(self.flow.signals), max_rate_hz=20,
                                                                   include_initial=True))
                async for response in stream:
                    for sample in response.samples:
                        self.values[sample.path] = (from_value(sample.value), sample.quality)
            except grpc.aio.AioRpcError as error:
                self.trace("warning", message=f"signal stream lost: {error.code().name}")
                for path in self.values:
                    self.values[path] = (self.values[path][0], pb.UNAVAILABLE)
                await asyncio.sleep(0.5)

    async def _fresh(self, timeout: float) -> bool:
        end = time.monotonic() + timeout
        while time.monotonic() < end:
            if all(self.values.get(p, (None, 0))[1] == pb.OK for p in self.flow.signals):
                return True
            await asyncio.sleep(0.05)
        return False

    # ------------------------------------------------------------ control lease

    async def _ensure_lease(self) -> pb.Lease:
        async with self.lease_lock:
            if self.lease is None:
                self.lease = await self.broker.AcquireControl(pb.AcquireRequest(client_id=f"rfrt:{self.run_id}"))
                self.tasks.append(asyncio.ensure_future(self._renew()))
                self.trace("lease", state="acquired")
            return self.lease

    async def _renew(self) -> None:
        while self.lease is not None and not self.stopping:
            await asyncio.sleep(max(0.1, self.lease.ttl_ms / 3000))
            try:
                await self.broker.RenewControl(self.lease)
            except grpc.aio.AioRpcError as error:
                self.trace("error", message=f"control lease lost: {error.details()}")
                self.lease = None
                return

    # ------------------------------------------------------------ primitives used by generated code

    async def command(self, node: str, path: str, args: dict) -> bool:
        try:
            lease = await self._ensure_lease()
        except grpc.aio.AioRpcError as error:
            self.trace("result", node=node, path=path, phase="REJECTED", message=error.details())
            return False
        request = pb.CommandRequest(lease_id=lease.lease_id, path=path, args=to_struct(args), request_id=str(uuid.uuid4()))
        phase = "FAILED"
        async for update in self.broker.Execute(request):
            phase = pb.CommandPhase.Name(update.phase)
            self.trace("command", node=node, path=path, requestId=update.request_id, phase=phase,
                       code=update.code, message=update.message)
        return phase == "SUCCEEDED"

    async def stop(self, node: str) -> bool:
        result = await self.safety.Stop(pb.StopRequest(request_id=str(uuid.uuid4()), source="WORKFLOW", reason=f"block {node}"))
        self.trace("command", node=node, path="Robot.Safety.Stop", requestId=result.request_id,
                   phase="SUCCEEDED" if result.confirmed else "FAILED", code=result.code, message=result.message)
        self.lease = None  # a stop ends control on the broker
        return result.confirmed

    async def move(self, node: str, linear: float, angular: float, duration_ms: int) -> bool:
        lease = await self._ensure_lease()
        end = time.monotonic() + duration_ms / 1000
        ok = True
        try:
            while time.monotonic() < end:
                ack = await self.broker.SetSetpoint(pb.SetpointRequest(
                    lease_id=lease.lease_id, path="Robot.Motion.Velocity", fields={"LinearX": linear, "AngularZ": angular}))
                if not ack.accepted:
                    self.trace("command", node=node, path="Robot.Motion.Velocity", phase="REJECTED", code=ack.code,
                               message=ack.message)
                    ok = False
                    break
                await asyncio.sleep(0.05)
        finally:
            await self.broker.SetSetpoint(pb.SetpointRequest(lease_id=lease.lease_id, path="Robot.Motion.Velocity",
                                                             fields={"LinearX": 0.0, "AngularZ": 0.0}))
        self.trace("command", node=node, path="Robot.Motion.Velocity", phase="SUCCEEDED" if ok else "FAILED")
        return ok

    async def wait(self, node: str, ms: int) -> None:
        await asyncio.sleep(ms / 1000)

    async def check(self, node: str, cond: Callable) -> bool | None:
        end = time.monotonic() + 1.0
        while True:
            try:
                result = bool(cond(self.v))
                self.trace("eval", node=node, result=result)
                return result
            except Stale as stale:
                if time.monotonic() > end:
                    self.trace("error", node=node, message=f"signal {stale} not fresh; branch stopped safely")
                    return None
                await asyncio.sleep(0.05)

    async def wait_until(self, node: str, cond: Callable, timeout_ms: int) -> bool:
        end = time.monotonic() + timeout_ms / 1000
        while time.monotonic() < end:
            try:
                if cond(self.v):
                    self.trace("eval", node=node, result=True)
                    return True
            except Stale:
                pass
            await asyncio.sleep(0.05)
        self.trace("eval", node=node, result=False, timeout=True)
        return False

    def repeat(self, node: str, count: int) -> bool:
        done = self.counters.get(node, 0)
        if done < count:
            self.counters[node] = done + 1
            self.trace("repeat", node=node, iteration=done + 1, of=count)
            return True
        self.counters[node] = 0
        return False

    def log(self, node: str, level: str, template: str) -> None:
        def value(match):
            try:
                v = self.v(match.group(1))
            except Stale:
                return "?"
            return f"{v:.2f}" if isinstance(v, float) else str(v)
        self.trace("log", node=node, level=level, message=TEMPLATE.sub(value, template))

    # ------------------------------------------------------------ behaviors

    async def run_chain(self, behavior: str, entry: str | None) -> None:
        node = entry
        steps = 0
        while node is not None and not self.stopping:
            steps += 1
            self.trace("node", node=node, state="started", behavior=behavior)
            started = time.monotonic()
            nxt = await self.flow.nodes[node](self)
            self.trace("node", node=node, state="finished", next=nxt, ms=round((time.monotonic() - started) * 1000))
            node = nxt
            if steps % 100 == 0:
                await asyncio.sleep(0)

    async def run_behavior(self, b: Behavior) -> None:
        self.trace("behavior", trigger=b.trigger, kind=b.kind, state="armed")
        if b.kind == "on_start":
            await self.run_chain(b.trigger, b.entry)
            return
        if b.kind == "every":
            while not self.stopping:
                await asyncio.sleep(b.period_ms / 1000)
                if b.trigger not in self.busy:
                    await self._fire(b)
            return
        holding_since = None
        fired = False
        while not self.stopping:
            try:
                true_now = bool(b.cond(self.v))
            except Stale:
                true_now, holding_since = False, None
            if true_now:
                holding_since = holding_since or time.monotonic()
                if not fired and time.monotonic() - holding_since >= b.for_ms / 1000:
                    fired = True
                    await self._fire(b)
                    if not b.repeat:
                        return
            else:
                holding_since, fired = None, False
            await asyncio.sleep(0.05)

    async def _fire(self, b: Behavior) -> None:
        self.busy.add(b.trigger)
        self.trace("behavior", trigger=b.trigger, kind=b.kind, state="fired")
        try:
            await self.run_chain(b.trigger, b.entry)
        finally:
            self.busy.discard(b.trigger)

    async def run(self) -> int:
        self.trace("run", state="started", version=VERSION, signals=len(self.flow.signals))
        code = 0
        async with grpc.aio.insecure_channel(self.broker_target) as channel, \
                grpc.aio.insecure_channel(self.safety_target) as safety_channel:
            self.broker, self.safety = rpc.BrokerStub(channel), rpc.SafetyLaneStub(safety_channel)
            self.tasks.append(asyncio.ensure_future(self._subscribe()))
            if not await self._fresh(10):
                self.trace("warning", message="some signals are not fresh yet; conditions wait for fresh data")
            behaviors = [asyncio.ensure_future(self.run_behavior(b)) for b in self.flow.behaviors]
            try:
                await asyncio.gather(*behaviors)
            except asyncio.CancelledError:
                code = 130
            except Exception as error:  # report, then release control safely
                self.trace("error", message=f"{type(error).__name__}: {error}")
                code = 1
            finally:
                self.stopping = True
                for task in behaviors + self.tasks:
                    task.cancel()
                if self.lease is not None:
                    try:
                        await self.broker.ReleaseControl(self.lease)
                    except grpc.aio.AioRpcError:
                        pass
                self.trace("run", state="finished", code=code)
        return code


def main(flow: Flow) -> None:
    runtime = Runtime(flow, os.environ.get("PB_BROKER", "protobus-broker:55500"),
                      os.environ.get("PB_SAFETY", "protobus-broker:55501"), os.environ.get("RF_RUN_ID", "local"))

    async def run() -> int:
        task = asyncio.ensure_future(runtime.run())
        loop = asyncio.get_running_loop()
        for sig in (signal.SIGTERM, signal.SIGINT):
            loop.add_signal_handler(sig, task.cancel)
        try:
            return await task
        except asyncio.CancelledError:
            return 130

    sys.exit(asyncio.run(run()))
